import ast
import functools
import json
import os
import string
from pathlib import Path

import regex
from unidecode import unidecode

source = Path('/baseline.py').read_text()
names = {'normalize_str', 'remove_dual_space', 'parse_words', 'contains_unicode', 'get_identifiers', 'pick_webhook', 'normalize_path', 'is_root_present'}
nodes = [node for node in ast.parse(source).body if isinstance(node, ast.FunctionDef) and node.name in names]
namespace = {'re': regex, 'lru_cache': functools.lru_cache, 'os': os, 'string': string, 'unidecode': unidecode, 'dual_space_pattern': regex.compile(r'(\s{2,})'), 'last_hook_index': None, 'discord_webhook_url': ['synthetic-channel-a', 'synthetic-channel-b']}
exec(compile(ast.Module(body=nodes, type_ignores=[]), '/baseline.py', 'exec'), namespace)
results = {}
try:
    namespace['normalize_str']('The Sample Manga', skip_type_keywords=True)
except UnboundLocalError as error:
    results['R15'] = {'observed': type(error).__name__, 'desired': 'skip_type_keywords remains usable without an uninitialized local'}
else:
    raise AssertionError('R15 not reproduced')
try:
    namespace['get_identifiers']('identifiers: synthetic-123')
except IndexError as error:
    results['R17'] = {'observed': type(error).__name__, 'desired': 'case-insensitive label parsing, explicit malformed-input outcome'}
else:
    raise AssertionError('R17 not reproduced')
words = namespace['parse_words']('Café')
assert words == ['café']
results['R16'] = {'observed': words, 'desired': ['cafe']}
hooks = [namespace['pick_webhook'](None) for _ in range(3)]
assert hooks == ['synthetic-channel-a'] * 3
results['R08'] = {'observed': hooks, 'desired': ['synthetic-channel-a', 'synthetic-channel-b', 'synthetic-channel-a']}
containment = namespace['is_root_present']('/books', '/books-old/series')
assert containment is True
results['R12'] = {'observed': containment, 'desired': False}
print(json.dumps({'scope': 'exact reviewed AST function bodies; explicit pure dependencies; no application import', 'results': results}, ensure_ascii=False))
